  async getContactList(nCaseid: string, contactFilter?: {}): Promise<selectedContactList[]> {
    let params = new HttpParams().set('nCaseid', nCaseid);
    if(Object.keys(contactFilter || {}).length > 0){
      for(const key in contactFilter){
        params = params.set(key, contactFilter[key]);
      }
    }
    let res: any = [];
    try {
      res = await firstValueFrom(
        this.http.get<selectedContactList[]>(
          `${environment.cloudUrl}${environment.coreservice}/contact/getcontactlist`, { params: params }
        )
      );
    } catch (error) {
      console.error(error)
      res = [];
    }
    return res;
  }

