  async getFileContactlist(nCaseid: string, jFilter: finalFilterList[], cSearch: string): Promise<any[]> {
    let params = new HttpParams().set('nCaseid', nCaseid);
    params = params.set('jFilter', JSON.stringify(jFilter || []));

    if (cSearch) {
      params = params.set('cSearch', cSearch);
    }

    let res: contactlistRes[] = [];
    try {
      res = await firstValueFrom(
        this.http.get<contactlistRes[]>(
          `${environment.cloudUrl}${environment.coreservice}/sidenav/contact/filecontacts`, { params: params }
        )
      );
      res = this.groupByCompany(res);
    } catch (error) {
      console.error(error)
      res = [];
    }
    return res;
  }



  groupByCompany(res) {
    let companylist = [];
    let company = {};
    res.forEach((element) => {
      if (!element.nCompanyid || element.nCompanyid == 0) {
        company = {
          "nCompanyid": 0,
          "cCompany": "Unassigned",
          "contactls": []
        }
      } else {
        company = {
          "nCompanyid": element.nCompanyid ? element.nCompanyid : 0,
          "cCompany": element.cCompany,
          "contactls": []
        }
      }
      let index = companylist.findIndex((x) => x.nCompanyid == (!company["nCompanyid"] ? 0 : company["nCompanyid"]));
      if (index > -1) {
        companylist[index].contactls.push(element);
      } else {
        company["contactls"].push(element);
        companylist.push(company);
      }
    });
    companylist[0].isopened = true;
    companylist[0].contactls[0].isopened = true;
    // this.getFactlist(companylist[0].contactls[0], companylist[0].contactls[0].nContactid, 0);
    return companylist;
  }




